"use strict";(self.webpackChunkbellplay_docs=self.webpackChunkbellplay_docs||[]).push([[7377],{8374:e=>{e.exports=JSON.parse('{"tag":{"label":"getkey","permalink":"/docs/tags/getkey","allTagsPath":"/docs/tags","count":23,"items":[{"id":"learn/examples/resynthesis","title":"1. Audio resynthesis","description":"A simple demonstration of granular quasi-resynthesis via partial tracks, where an sound is used to guide the behavior of sinusoidal grains.","permalink":"/docs/learn/examples/resynthesis"},{"id":"learn/examples/audiomosaic","title":"10. Audio mosaicing","description":"An example of basic audio mosaicking in bellplay~, where a target audio file is reconstructed using segments drawn from a small audio corpus.","permalink":"/docs/learn/examples/audiomosaic"},{"id":"learn/examples/temporalalignment","title":"11. Envelope-aware temporal alignment","description":"This example demonstrates how to align the envelopes of different audio samples based on their peak amplitude times.","permalink":"/docs/learn/examples/temporalalignment"},{"id":"learn/examples/shepardtone","title":"12. Shepard-Risset glissando","description":"This example synthesizes a Shepard-Risset glissando using bellplay~.","permalink":"/docs/learn/examples/shepardtone"},{"id":"learn/examples/keymaps","title":"13. Generating keymaps","description":"This example automatically generates a custom keymap given a list of audio file paths:","permalink":"/docs/learn/examples/keymaps"},{"id":"learn/tutorials/bufferinspector","title":"14. Inspecting buffers","description":"An essential part of writing code is being able to debug unwanted or unexpected behaviors.","permalink":"/docs/learn/tutorials/bufferinspector"},{"id":"learn/examples/neuralsynth","title":"14. Neural synthesizer","description":"This tutorial demonstrates how to use a multi-layer perceptron (MLP) neural network","permalink":"/docs/learn/examples/neuralsynth"},{"id":"learn/tutorials/analysis","title":"15. Audio descriptors","description":"One of the core features in bellplay~ is our ability to analyze buffers to extract relevant information.","permalink":"/docs/learn/tutorials/analysis"},{"id":"learn/tutorials/analysismodes","title":"16. Audio descriptor modes","description":"When analyzing buffers, we can specify the output format for many of the available audio descriptors.","permalink":"/docs/learn/tutorials/analysismodes"},{"id":"learn/tutorials/features","title":"17. More audio features","description":"This tutorial provides an additional example for using buffer analysis features for audio processing.","permalink":"/docs/learn/tutorials/features"},{"id":"learn/tutorials/caching","title":"19. Caching data","description":"In bellplay~, computation-heavy operations such as building large corpora, analyzing lots of audio data, and more, can be take a very long time, thus making it more tedious to experiment with our scripts every time we run them.","permalink":"/docs/learn/tutorials/caching"},{"id":"learn/examples/basicgranulation","title":"2. Basic granulation","description":"An example of basic audio granulation, where short audio.","permalink":"/docs/learn/examples/basicgranulation"},{"id":"learn/tutorials/importingmidi","title":"22. Importing MIDI","description":"bellplay~ supports importing MIDI files (.mid or .midi) into our scripts, each described as a list of events.","permalink":"/docs/learn/tutorials/importingmidi"},{"id":"learn/tutorials/kdtree","title":"24. Feature-driven sampling","description":"This tutorial shows how to build k-dimensional trees to efficiently perform feature-based search on buffers.","permalink":"/docs/learn/tutorials/kdtree"},{"id":"learn/tutorials/sourceseparation","title":"25. Audio source separation","description":"This tutorial demonstrates how to perform rudimentary source separation","permalink":"/docs/learn/tutorials/sourceseparation"},{"id":"learn/examples/waveshaping","title":"5. Waveshaping buffers","description":"A basic example of waveshaping in bellplay~, using a randomly generated breakpoint function.","permalink":"/docs/learn/examples/waveshaping"},{"id":"learn/tutorials/bufferkeys","title":"6. Buffer keys","description":"Buffers in bellplay~ are simply structured lists of key-value pairs.","permalink":"/docs/learn/tutorials/bufferkeys"},{"id":"learn/examples/markov","title":"7. Markov music generation","description":"This script illustrates how to construct and use an nth-order Markov model from MIDI data in bellplay~ for generative music.","permalink":"/docs/learn/examples/markov"},{"id":"learn/examples/midiretuning","title":"8. MIDI retuning","description":"An example of JI-based retuning of MIDI events.","permalink":"/docs/learn/examples/midiretuning"},{"id":"learn/examples/temporalquantization","title":"9. Temporal quantization","description":"A basic example of temporal quantization, where transient-based segments are temporally shifted to align with a rhythmic grid.","permalink":"/docs/learn/examples/temporalquantization"},{"id":"reference/data-utilities/mapkey","title":"mapkey","description":"mapkey","permalink":"/docs/reference/data-utilities/mapkey"},{"id":"reference/data-utilities/parsepath","title":"parsepath","description":"parsepath","permalink":"/docs/reference/data-utilities/parsepath"},{"id":"reference/data-utilities/setkey","title":"setkey","description":"setkey","permalink":"/docs/reference/data-utilities/setkey"}],"unlisted":false}}')}}]);